       updated_at = updated_at + INTERVAL @d DAY, deleted_at = deleted_at + INTERVAL @d DAY;
UPDATE login_attempts SET attempted_at = attempted_at + INTERVAL @d DAY;
UPDATE patients SET created_at = created_at + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY,
       deleted_at = deleted_at + INTERVAL @d DAY;
UPDATE visits SET started_at = started_at + INTERVAL @d DAY, ended_at = ended_at + INTERVAL @d DAY,
       created_at = created_at + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY,
       deleted_at = deleted_at + INTERVAL @d DAY;
