UPDATE medicines SET created_at = created_at + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY;
UPDATE supplies SET created_at = created_at + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY;
UPDATE medicine_stock SET expiry_date = expiry_date + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY;
UPDATE supply_stock SET expiry_date = expiry_date + INTERVAL @d DAY, updated_at = updated_at + INTERVAL @d DAY;
UPDATE visit_medicines SET given_at = given_at + INTERVAL @d DAY;
UPDATE visit_supplies SET given_at = given_at + INTERVAL @d DAY;
UPDATE stock_requests SET request_date = request_date + INTERVAL @d DAY, approved_at = approved_at + INTERVAL @d DAY,
       received_at = received_at + INTERVAL @d DAY;
